window.AUTH=window.AUTH||{};window.AUTH["18-328"]={"d":"18-328","id":"2019/18-328","n":"Rotkiske v. Klemm","briefs":[{"k":"petitioner","label":"Brief of petitioner Kevin Rotkiske","date":"2019-05-13","url":"https://www.supremecourt.gov/DocketPDF/18/18-328/99432/20190513131857769_Brief%20for%20Petitioner.pdf","side":"pet","n":68},{"k":"respondent","label":"Brief of respondents Paul Klemm, et al.","date":"2019-07-12","url":"https://www.supremecourt.gov/DocketPDF/18/18-328/107972/20190712154545339_18-328%20bs.pdf","side":"res","n":56},{"k":"united-states","label":"Brief amicus curiae of United States","date":"2019-07-18","url":"https://www.supremecourt.gov/DocketPDF/18/18-328/108547/20190718160036768_18-328bsacUnitedStates.pdf","side":"us","n":109},{"k":"reply","label":"Reply of petitioner Kevin Rotkiske","date":"2019-08-12","url":"https://www.supremecourt.gov/DocketPDF/18/18-328/111973/20190812133036148_Reply%20Brief.pdf","side":"pet","n":23}],"opinion":"https://www.supremecourt.gov/opinions/preliminaryprint/589US1PP_Web.pdf#page=49","tr":true,"items":[{"t":"case","label":"American Pipe & Constr. Co. v. Utah","cite":"414 U.S. 538","y":1974,"id":"1973/72-1195","sc":1,"ar":1,"sum":"The Court held that commencing a class action suspends all applicable statutes of limitations against members of that class who would have been parties had the suit been allowed to continue as a class action.","sumSrc":"Oyez","by":{"0":"27, 39, 40","1":"38","2":"25"}},{"t":"case","label":"Artis v. District of Columbia","cite":"138 S. Ct. 594","y":2018,"id":"2017/16-460","sc":1,"sum":"The Court decided that the tolling provision of 28 U.S.C. § 1367 suspends or “stops the clock” on the limitations period for supplemental state law claims while the underlying case is pending in federal court and for 30 days thereafter, rather than merely providing a 30-day grace period after dismissal for the plaintiff to refile in state court.","sumSrc":"Oyez","by":{"0":"39"}},{"t":"case","label":"Astoria Fed. Sav. & Loan Ass’n v. Solimino","cite":"501 U.S. 104","y":1991,"id":"1990/89-1895","sc":1,"sum":"Judicially unreviewed state administrative findings have no preclusive effect on age-discrimination proceedings in federal court. While well-established common-law principles, such as preclusion rules, are presumed to apply in the absence of a legislative intent to the contrary, Congress need not state expressly its intention to overcome a presumption of administrative estoppel. Clear-statement requirements are …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"19","2":"15"}},{"t":"case","label":"Bailey v. Glover","cite":"88 U.S. 342","y":1874,"id":"scdb/1874-150","sc":1,"op":4,"sum":"Bailey, assignee in bankruptcy of Benjamin Glover, and appointed as such December 1st, 1869, filed a bill on the 20th of January, 1873 (three years and seven weeks, therefore, after the date of his appointment) against Elenora Glover, wife of the bankrupt, Hugh Weir, his father-in-law, and Nathaniel Glover, his son, to set aside certain conveyances.","sumSrc":"Headnote (U.S. Reports)","by":{"0":"passim"}},{"t":"case","label":"Bay Area Laundry & Dry Cleaning Pension Trust Fund v. Ferbar Corp. of Cal., Inc.","cite":"522 U.S. 192","y":1997,"id":"1997/96-370","sc":1,"op":1,"sum":"The Court held that the MPPAA's six-year statute of limitations on a pension fund's action to collect unpaid withdrawal liability does not begin to run until the employer fails to make a payment on the schedule set by the fund.","sumSrc":"Oyez","by":{"0":"40-41","1":"29, 30, 31","2":"14"}},{"t":"case","label":"Board of Regents of Univ. of State of New York v. Tomanio","cite":"446 U.S. 478","y":1980,"id":"1979/79-424","sc":1,"sum":"Respondent's action was barred by the New York statute of limitations. The federal courts were obligated not only to apply the analogous New York statute of limitations to respondent's federal constitutional claims, but also to apply the New York rule for tolling that statute of limitations. Robertson v. Wegmann, 436 U. S. 584; Johnson v. Railway BOARD OF REGENTS v. TOMANIO","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"39"}},{"t":"case","label":"California Pub. Emps.’ Ret. Sys. v. ANZ Secs., Inc.","cite":"137 S. Ct. 2042","y":2017,"id":"2016/16-373","sc":1,"op":1,"sum":"The Court determined that the filing of a putative class action lawsuit does not satisfy the three-year time limit in Section 13 of the Securities Act with respect to the individual claims of other class members.","sumSrc":"Oyez","by":{"0":"15-16, 17, 20","1":"38","2":"22, 23, 24, 25, 26","3":"1"}},{"t":"case","label":"Chaudhry v. Gallerizzo","cite":"174 F.3d 394","y":1999,"court":"4th Cir.","url":"https://www.courtlistener.com/c/F.3d/174/394/","by":{"0":"31"}},{"t":"case","label":"China Agritech, Inc. v. Resh","cite":"138 S. Ct. 1800","y":2018,"id":"2017/17-432","sc":1,"sum":"The Court decided that upon denial of class certification, a putative class member may not, in lieu of promptly joining an existing suit or promptly filing a individual action, commence a class action anew beyond the time allowed by the applicable statute of limitations.","sumSrc":"Oyez","by":{"0":"18"}},{"t":"case","label":"Corley v. United States","cite":"556 U.S. 303","y":2009,"id":"2008/07-10441","sc":1,"sum":"The Court found that voluntary confessions made more than six hours after arrest before the person has been presented before judicial officers are inadmissible.","sumSrc":"Oyez","by":{"0":"37"}},{"t":"case","label":"CTS Corp. v. Waldburger","cite":"573 U.S. 1","y":2014,"id":"2013/13-339","sc":1,"sum":"The Court found that the Comprehensive Environmental Response, Compensation, and Liability Act pre-empts statutes of limitations, but cannot be used to pre-empt statutes of repose.","sumSrc":"Oyez","by":{"0":"10, 17, 18"}},{"t":"case","label":"Davis v. Michigan Dep’t of Treasury","cite":"489 U.S. 803","y":1989,"id":"1988/87-1020","sc":1,"sum":"Section 111 allows a state to tax income paid by the federal government \"if the taxation does not discriminate against the officer or employee because of the source of the pay or compensation.\" Because the Court found no \"significant differences between the two classes [federal and state employees],\" it held that the Michigan tax distinguished between employees solely on \"the source of the pay.\".","sumSrc":"Oyez","by":{"0":"29"}},{"t":"case","label":"Exploration Co. v. United States","cite":"247 U.S. 435","y":1918,"id":"scdb/1917-126","sc":1,"op":2,"ar":7,"sum":"Statutes of limitation upon suits to set aside fraudulent transactions do not begin to run until discovery of the fraud. Bailey v. Glover, 21 Wall. 342.","sumSrc":"Headnote (U.S. Reports)","by":{"0":"20, 23, 24, 40","1":"38, 43","2":"29, 30, 31","3":"passim"}},{"t":"case","label":"Fouts v. Express Recovery Servs., Inc.","cite":"602 F. App’x 417","y":2015,"court":"10th Cir.","url":"https://www.courtlistener.com/c/F.%20App%E2%80%99x/602/417/","by":{"0":"31"}},{"t":"case","label":"Gabelli v. SEC","cite":"568 U.S. 442","y":2013,"id":"2012/11-1274","sc":1,"op":3,"ar":3,"sum":"The Court held that a five-year statute of limitations period begins at the time the violation is committed.","sumSrc":"Oyez","by":{"0":"28","1":"passim","2":"10, 14, 28","3":"4"}},{"t":"case","label":"Glus v. Brooklyn E. Dist. Terminal","cite":"359 U.S. 231","y":1959,"id":"1958/446","sc":1,"sum":"If petitioner can prove that respondent's responsible agents conducted themselves in such a way that he was justifiably misled into a good-faith belief that he could begin his action at any time within seven years after it accrued, he is entitled to have his case tried on the merits, and the District Court erred in dismissing the case on the ground that it was barred by the three-year limitation. Pp. 231-235. 253 F. …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"26","1":"38, 39, 40","2":"25"}},{"t":"case","label":"Gonzales v. Arrow Fin. Servs., LLC","cite":"660 F.3d 1055","y":2011,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/660/1055/","by":{"0":"31"}},{"t":"case","label":"Gonzalez v. Kay","cite":"577 F.3d 600","y":2009,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.3d/577/600/","by":{"0":"31"}},{"t":"case","label":"Graham Cty. Soil & Water Conservation Dist. v. United States ex rel. Wilson","cite":"559 U.S. 280","y":2010,"id":"2009/08-304","sc":1,"op":1,"sum":"The Court held that an audit performed by a state or its political subdivisions constitutes an administrative report within the False Claims Act.","sumSrc":"Oyez","by":{"0":"29"}},{"t":"case","label":"Green v. Brennan","cite":"136 S. Ct. 1769","y":2016,"id":"2015/14-613","sc":1,"sum":"The Court held that the 45-day period in which an employee must file a constructive discharge claim under federal employment discrimination law begins to run on the date the employee resigns.","sumSrc":"Oyez","by":{"0":"37, 38","1":"7, 30"}},{"t":"case","label":"Henson v. Santander Consumer USA Inc.","cite":"137 S. Ct. 1718","y":2017,"id":"2016/16-349","sc":1,"sum":"The Court determined that a party that purchases a debt and attempts to collect the debt for its own account is not a “debt collector” subject to the Fair Debt Collection Practices Act (FDCPA).","sumSrc":"Oyez","by":{"0":"4, 29","2":"22"}},{"t":"case","label":"Holmberg v. Armbrecht","cite":"327 U.S. 392","y":1946,"id":"scdb/1945-049","sc":1,"op":6,"ar":12,"sum":"1. Decision of a suit in a federal court to enforce a federally created equitable right is not controlled by the statute of limitations of the State of the forum. Guaranty Trust Co. v. York, 326 U. S. 99, distinguished. Accordingly, a class suit by creditors of a joint stock land bank to enforce the liability imposed upon shareholders of the bank by § 16 of the Federal Farm Loan Act is not barred by the state …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"24, 25, 26, 28","1":"37, 38","2":"12, 24, 30","3":"passim"}},{"t":"case","label":"Honda v. Clark","cite":"386 U.S. 484","y":1967,"id":"1966/164","sc":1,"sum":"This suit was brought by 4,100 citizens or residents of the United States who were depositors, holding \"yen certificates,\" in the Yokohama Specie Bank (YSB). In 1943 the Alien Property Custodian had vested as enemy property the assets of YSB located in the United States. In 1946 Congress provided in § 34 of the Trading with the Enemy Act for the payment from the vested assets to American citizen or resident …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"38-39"}},{"t":"case","label":"Irwin v. Department of Veterans Affairs","cite":"498 U.S. 89","y":1990,"id":"1990/89-5867","sc":1,"sum":"The Supreme Court held that lower courts have consistently held that notice to an attorney's office qualifies as notice to the client. \"The practical effect of a contrary rule would be to encourage factual disputes about when actual notice was received, and thereby create uncertainty in an area of the law where certainty is much to be desired,\" wrote Chief Justice Rehnquist.","sumSrc":"Oyez","by":{"0":"10","1":"8","2":"25"}},{"t":"case","label":"Jerman v. Carlisle, McNellie, Rini, Kramer & Ulrich LPA","cite":"559 U.S. 573","y":2010,"id":"2009/08-1200","sc":1,"op":1,"sum":"The Court held that a debt collector's mistake in interpreting the law cannot qualify for the Fair Debt Collection Practices Act bona fide error defense.","sumSrc":"Oyez","by":{"0":"passim","1":"25","2":"3"}},{"t":"case","label":"John R. Sand & Gravel Co. v. United States","cite":"552 U.S. 130","y":2008,"id":"2007/06-1164","sc":1,"sum":"In a seven-member majority opinion written by Justice Stephen G. Breyer, the Court upheld the Federal Circuit ruling that the statute of limitations was \"jurisdictional,\" or a predicate for court authority. Breyer referred to roughly five decades of the Court's case law to determine that the doctrine of stare decisis required it to follow the time limit and dismiss John R. Sand's claim.","sumSrc":"Oyez","by":{"0":"17, 39-40"}},{"t":"case","label":"Jones v. R.R. Donnelley & Sons Co.","cite":"541 U.S. 369","y":2004,"id":"2003/02-1205","sc":1,"sum":"It also applies to amendments of previously existing laws. Writing for a unanimous Court, Justice John Paul Stevens stated \"[a]n amendment to an existing statute is no less an 'Act of Congress' than a new, stand-alone statute.\" The four-year statute of limitations therefore applies to any act or amendment to an act passed by Congress after 1990.","sumSrc":"Oyez","by":{"0":"37-38"}},{"t":"case","label":"King v. Burwell","cite":"135 S. Ct. 2480","y":2015,"id":"2014/14-114","sc":1,"sum":"The Court determined that the plain language of the Affordable Care Act extended tax credits to federally-created exchanges as well as those the states created.","sumSrc":"Oyez","by":{"0":"29","3":"10"}},{"t":"case","label":"Kolbasyuk v. Capital Mgmt. Servs., LP","cite":"918 F.3d 236","y":2019,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/918/236/","by":{"0":"31"}},{"t":"case","label":"Lampf, Pleva, Lipkind, Prupis & Petigrow v. Gilbertson","cite":"501 U.S. 350","y":1991,"id":"1990/90-333","sc":1,"op":1,"ar":1,"sum":"The judgment is reversed. 895 F. 2d 1416, 1417, and 1418, reversed. JUSTICE BLACKMUN delivered the opinion of the Court with respect to Parts I, II-B, II-C, III, and IV, concluding that:","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"17","1":"36","2":"25, 31"}},{"t":"case","label":"LeBlanc v. Unifund CCR Partners","cite":"601 F.3d 1185","y":2010,"court":"11th Cir.","url":"https://www.courtlistener.com/c/F.3d/601/1185/","by":{"0":"31"}},{"t":"case","label":"Levins v. Healthcare Revenue Recov. Grp. LLC","cite":"902 F.3d 274","y":2018,"court":"3d Cir.","url":"https://www.courtlistener.com/c/F.3d/902/274/","by":{"0":"31"}},{"t":"case","label":"Lozano v. Montoya Alvarez","cite":"572 U.S. 1","y":2014,"id":"2013/12-820","sc":1,"op":3,"ar":1,"sum":"The Court held that the policy of equitable tolling does not apply to the statute of limitations outlined in the Hauge Convention's provision on international child abduction.","sumSrc":"Oyez","by":{"0":"10, 20","1":"8, 15, 38","2":"23, 25, 31","3":"4-5"}},{"t":"case","label":"Macy v. GC Servs. Ltd. P’ship","cite":"897 F.3d 747","y":2018,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.3d/897/747/","by":{"0":"31"}},{"t":"case","label":"Merck & Co., Inc. v. Reynolds","cite":"559 U.S. 633","y":2010,"id":"2009/08-905","sc":1,"op":3,"ar":2,"sum":"The Court held that a statute of limitations begins to run once a plaintiff actually discovers -- or a reasonably diligent plaintiff would have discovered -- the facts constituting the violation in the present case, whichever comes first.","sumSrc":"Oyez","by":{"0":"15, 20, 25, 28","1":"7, 24","2":"10, 13, 31","3":"4, 14"}},{"t":"case","label":"Meyer v. Holley","cite":"537 U.S. 280","y":2003,"id":"2002/01-1120","sc":1,"sum":"The Court held that the FHA imposes liability without fault upon the employer in accordance with traditional agency principles. In other words, the FHA normally imposes vicarious liability upon the corporation, but not upon its officers or owners.","sumSrc":"Oyez","by":{"0":"20"}},{"t":"case","label":"Midland Funding, LLC v. Johnson","cite":"137 S. Ct. 1407","y":2017,"id":"2016/16-348","sc":1,"sum":"The Court determined that the Fair Debt Collection Practices Act (FDCPA) does not prevent a creditor from filing a proof of claim on an unpaid debt in a Chapter 13 bankruptcy proceeding even after the statute of limitations on that debt has run.","sumSrc":"Oyez","by":{"0":"3, 5"}},{"t":"case","label":"New Prime Inc. v. Oliveira","cite":"139 S. Ct. 532","y":2019,"id":"2018/17-340","sc":1,"sum":"A court should determine whether the Federal Arbitration Act’s §1 exclusion for disputes involving the “contracts of employment” of certain transportation workers applies before ordering arbitration; here, truck driver Oliveira’s independent contractor operating agreement with New Prime falls within that exception.","sumSrc":"Holding (supremecourt.gov)","by":{"0":"16"}},{"t":"case","label":"O’Boyle v. Real Time Resolutions, Inc.","cite":"910 F.3d 338","y":2018,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/910/338/","by":{"0":"31"}},{"t":"case","label":"Pace v. DiGuglielmo","cite":"544 U.S. 408","y":2005,"id":"2004/03-9627","sc":1,"sum":"The Court held that the federal statute of limitations barred Pace's petition, as it was filed beyond the deadline. Pace was not entitled to statutory tolling because a petition filed after a time limit, which does meet any exceptions to that limit, was no more \"properly filed\" than a petition filed after a time limit permitting no exception.","sumSrc":"Oyez","by":{"0":"9-10"}},{"t":"case","label":"Petrella v. Metro-Goldwyn-Mayer, Inc.","cite":"572 U.S. 663","y":2014,"id":"2013/12-1315","sc":1,"sum":"The Court held that the doctrine of laches could not be used to prevent a copyright suit that seeks relief for damages that occurred within the three-year window allowed by the Copyright Act.","sumSrc":"Oyez","by":{"0":"9, 17","2":"14, 25"}},{"t":"case","label":"Pollard v. Law Office of Mandy L. Spaulding","cite":"766 F.3d 98","y":2014,"court":"1st Cir.","url":"https://www.courtlistener.com/c/F.3d/766/98/","by":{"0":"31"}},{"t":"case","label":"Reiter v. Cooper","cite":"507 U.S. 258","y":1993,"id":"1992/91-1496","sc":1,"sum":"The Interstate Commerce Act (ICA) requires that motor common carriers charge the tariff rates they file with the Interstate Commerce Commission (ICC), 49 U. S. C. § 10762, and that such rates be \"reasonable,\" § 10701(a). Between 1984 and 1986, petitioner shippers tendered shipments to Carolina Motor Express, Inc., a motor carrier subject to ICC regulation, at negotiated rates that were lower than the applicable …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"36-37"}},{"t":"case","label":"Rotella v. Wood","cite":"528 U.S. 549","y":2000,"id":"1999/98-896","sc":1,"op":1,"ar":3,"sum":"The Court held that Rotella's action was not timely, because the start of the 4-year limitations period applicable to a civil RICO action was not governed by an \"injury and pattern discovery\" accrual rule under which such a civil claim would accrue only when the claimant discovered, or should have discovered, both an injury and a pattern of racketeering activity.","sumSrc":"Oyez","by":{"0":"28","1":"7, 13, 23, 24","2":"20, 21, 22, 25"}},{"t":"case","label":"SCA Hygiene Prods. Aktiebolag v. First Quality Baby Prods., LLC","cite":"137 S. Ct. 954","y":2017,"id":"2016/15-927","sc":1,"sum":"The Court determined that an unreasonable delay in litigation cannot bar claims for patent infringement that are brought within the six-year statutory period of limitations.","sumSrc":"Oyez","by":{"0":"19"}},{"t":"case","label":"Scheffler v. Gurstel Chargo, P.A.","cite":"902 F.3d 757","y":2018,"court":"8th Cir.","url":"https://www.courtlistener.com/c/F.3d/902/757/","by":{"0":"31"}},{"t":"case","label":"Sheriff v. Gillie","cite":"136 S. Ct. 1594","y":2016,"id":"2015/15-338","sc":1,"sum":"The Court held that, regardless of whether special counsel appointed by the Attorney General to collect debts are “state officers” under the Federal Debt Collection Practices Act, the use of Attorney General letterhead by such special counsel is not materially misleading.","sumSrc":"Oyez","by":{"0":"3"}},{"t":"case","label":"Smith v. United States","cite":"568 U.S. 106","y":2013,"id":"2012/11-8976","sc":1,"sum":"The Court held that the burden lies on the defendant, instead of the government, to prove withdrawal from a conspiracy regardless of when the withdrawal took place.","sumSrc":"Oyez","by":{"0":"19-20"}},{"t":"case","label":"Sykes v. Harris","cite":"2016 WL 3030156","y":2016,"court":"S.D.N.Y. May 24","by":{"0":"12"}},{"t":"case","label":"Sykes v. Mel S. Harris & Assocs. LLC","cite":"780 F.3d 70","y":2015,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/780/70/","by":{"0":"12"}},{"t":"case","label":"TRW Inc. v. Andrews","cite":"534 U.S. 19","y":2001,"id":"2001/00-1045","sc":1,"op":5,"sum":"The Court held that a discovery rule does not govern section 1681p of FCRA, as that section explicitly delineated the exceptional case in which discovery triggered the two-year limitation and Adelaide's case does not fall within the exceptional category. The Court reasoned that it was not at liberty to make Congress' explicit exception the general rule.","sumSrc":"Oyez","by":{"0":"25, 28","1":"passim","2":"7, 16, 17, 18","3":"7, 8, 14"}},{"t":"case","label":"United States v. Brockamp","cite":"519 U.S. 347","y":1997,"id":"1996/95-1225","sc":1,"sum":"The Court ruled that Congress did not intend the \"equitable tolling\" doctrine to apply to the Internal Revenue Code of 1986's time limitations for filing tax refund claims.","sumSrc":"Oyez","by":{"0":"17"}},{"t":"case","label":"United States v. Welden","cite":"377 U.S. 95","y":1964,"id":"1963/235","sc":1,"sum":"Appellee's testimony before the congressional subcommittee did not immunize him from prosecution, the Act of February 25, 1903, as amended in 1906, confining immunity to persons who testify in judicial proceedings under oath and in response to a subpoena. 215 F. Supp. 656, reversed and remanded.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"2"}},{"t":"case","label":"United States v. Wells","cite":"519 U.S. 482","y":1997,"id":"1996/95-1228","sc":1,"sum":"Authored by Justice David H. Souter, the Court ruled that the materiality of falsehood is not an element of the crime of knowingly making a false statement to a federally insured bank. Justice Souter wrote for the court that prosecutors need not prove that a lie was relevant enough to affect the outcome of a bank's decision because the law does not require such materiality.","sumSrc":"Oyez","by":{"0":"20","2":"15"}},{"t":"case","label":"Urie v. Thompson","cite":"337 U.S. 163","y":1949,"id":"scdb/1948-083","sc":1,"sum":"1. The coverage of the Federal Employers' Liability Act and the Boiler Inspection Act is not confined to injuries resulting from accidents but includes injuries in the nature of occupational diseases, such as silicosis. Pp. 173-175, 180-196.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"25, 26, 40","2":"11, 15, 16, 17"}},{"t":"usc","label":"15 U.S.C. § 1692","url":"https://www.law.cornell.edu/uscode/text/15/1692","subs":["(e)"],"stext":{"head":"§1692. Congressional findings and declaration of purpose","paras":[[0,"(a) Abusive practices"],[0,"There is abundant evidence of the use of abusive, deceptive, and unfair debt collection practices by many debt collectors. Abusive debt collection practices contribute to the number of personal bankruptcies, to marital instability, to the loss of jobs, and to invasions of individual privacy."],[0,"(b) Inadequacy of laws"],[0,"Existing laws and procedures for redressing these injuries are inadequate to protect consumers."],[0,"(c) Available non-abusive collection methods"],[0,"Means other than misrepresentation or other abusive debt collection practices are available for the effective collection of debts."],[0,"(d) Interstate commerce"],[0,"Abusive debt collection practices are carried on to a substantial extent in interstate commerce and through means and instrumentalities of such commerce. Even where abusive debt collection practices are purely intrastate in character, they nevertheless directly affect interstate commerce."],[0,"(e) Purposes"],[0,"It is the purpose of this subchapter to eliminate abusive debt collection practices by debt collectors, to insure that those debt collectors who refrain from using abusive debt collection practices are not competitively disadvantaged, and to promote consistent State action to protect consumers against debt collection abuses."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/15/1692?type=usc&year=mostrecent&link-type=html"},"head":"§1692. Congressional findings and declaration of purpose","tname":"Commerce and Trade","by":{"0":"3, 29","1":"passim","2":"1, 21"}},{"t":"usc","label":"15 U.S.C. § 1692b","url":"https://www.law.cornell.edu/uscode/text/15/1692b","stext":{"head":"§1692b. Acquisition of location information","paras":[[0,"Any debt collector communicating with any person other than the consumer for the purpose of acquiring location information about the consumer shall—"],[1,"(1) identify himself, state that he is confirming or correcting location information concerning the consumer, and, only if expressly requested, identify his employer;"],[1,"(2) not state that such consumer owes any debt;"],[1,"(3) not communicate with any such person more than once unless requested to do so by such person or unless the debt collector reasonably believes that the earlier response of such person is erroneous or incomplete and that such person now has correct or complete location information;"],[1,"(4) not communicate by post card;"],[1,"(5) not use any language or symbol on any envelope or in the contents of any communication effected by the mails or telegram that indicates that the debt collector is in the debt collection business or that the communication relates to the collection of a debt; and"],[1,"(6) after the debt collector knows the consumer is represented by an attorney with regard to the subject debt and has knowledge of, or can readily ascertain, such attorney's name and address, not communicate with any person other than that attorney, unless the attorney fails to respond within a reasonable period of time to communication from the debt collector."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/15/1692b?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§1692b. Acquisition of location information","tname":"Commerce and Trade","by":{"0":"31","2":"21"}},{"t":"usc","label":"15 U.S.C. § 1692c","url":"https://www.law.cornell.edu/uscode/text/15/1692c","subs":["(a)","(a)(1)","(a)(2)","(a)(3)","(b)","(c)"],"stext":{"head":"§1692c. Communication in connection with debt collection","paras":[[0,"(a) Communication with the consumer generally"],[0,"Without the prior consent of the consumer given directly to the debt collector or the express permission of a court of competent jurisdiction, a debt collector may not communicate with a consumer in connection with the collection of any debt—"],[1,"(1) at any unusual time or place or a time or place known or which should be known to be inconvenient to the consumer. In the absence of knowledge of circumstances to the contrary, a debt collector shall assume that the convenient time for communicating with a consumer is after 8 o'clock antemeridian and before 9 o'clock postmeridian, local time at the consumer's location;"],[1,"(2) if the debt collector knows the consumer is represented by an attorney with respect to such debt and has knowledge of, or can readily ascertain, such attorney's name and address, unless the attorney fails to respond within a reasonable period of time to a communication from the debt collector or unless the attorney consents to direct communication with the consumer; or"],[1,"(3) at the consumer's place of employment if the debt collector knows or has reason to know that the consumer's employer prohibits the consumer from receiving such communication."],[0,"(b) Communication with third parties"],[0,"Except as provided in section 1692b of this title, without the prior consent of the consumer given directly to the debt collector, or the express permission of a court of competent jurisdiction, or as reasonably necessary to effectuate a postjudgment judicial remedy, a debt collector may not communicate, in connection with the collection of any debt, with any person other than the consumer, his attorney, a consumer reporting agency if otherwise permitted by law, the creditor, the attorney of the creditor, or the attorney of the debt collector."],[0,"(c) Ceasing communication"],[0,"If a consumer notifies a debt collector in writing that the consumer refuses to pay a debt or that the consumer wishes the debt collector to cease further communication with the consumer, the debt collector shall not communicate further with the consumer with respect to such debt, except—"],[1,"(1) to advise the consumer that the debt collector's further efforts are being terminated;"],[1,"(2) to notify the consumer that the debt collector or creditor may invoke specified remedies which are ordinarily invoked by such debt collector or creditor; or"],[1,"(3) where applicable, to notify the consumer that the debt collector or creditor intends to invoke a specified remedy."],[0,"If such notice from the consumer is made by mail, notification shall be complete upon receipt."],[0,"(d) \"Consumer\" defined"],[0,"For the purpose of this section, the term \"consumer\" includes the consumer's spouse, parent (if the consumer is a minor), guardian, executor, or administrator."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/15/1692c?type=usc&year=mostrecent&link-type=html"},"head":"§1692c. Communication in connection with debt collection","tname":"Commerce and Trade","by":{"0":"32, 33","1":"4, 32","2":"2, 19, 19, 20, 2, 21, 19"}},{"t":"usc","label":"15 U.S.C. § 1692d","url":"https://www.law.cornell.edu/uscode/text/15/1692d","subs":["(3)","(4)"],"stext":{"head":"§1692d. Harassment or abuse","paras":[[0,"A debt collector may not engage in any conduct the natural consequence of which is to harass, oppress, or abuse any person in connection with the collection of a debt. Without limiting the general application of the foregoing, the following conduct is a violation of this section:"],[1,"(1) The use or threat of use of violence or other criminal means to harm the physical person, reputation, or property of any person."],[1,"(2) The use of obscene or profane language or language the natural consequence of which is to abuse the hearer or reader."],[1,"(3) The publication of a list of consumers who allegedly refuse to pay debts, except to a consumer reporting agency or to persons meeting the requirements of section 1681a(f) or 1681b(3) 1 of this title."],[1,"(4) The advertisement for sale of any debt to coerce payment of the debt."],[1,"(5) Causing a telephone to ring or engaging any person in telephone conversation repeatedly or continuously with intent to annoy, abuse, or harass any person at the called number."],[1,"(6) Except as provided in section 1692b of this title, the placement of telephone calls without meaningful disclosure of the caller's identity."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/15/1692d?type=usc&year=mostrecent&link-type=html"},"head":"§1692d. Harassment or abuse","tname":"Commerce and Trade","by":{"0":"33-34","1":"3, 32","2":"2, 19, 21, 21"}},{"t":"usc","label":"15 U.S.C. § 1692e","url":"https://www.law.cornell.edu/uscode/text/15/1692e","subs":["(2)","(2)(A)","(2)(B)","(5)"],"stext":{"head":"§1692e. False or misleading representations","paras":[[0,"A debt collector may not use any false, deceptive, or misleading representation or means in connection with the collection of any debt. Without limiting the general application of the foregoing, the following conduct is a violation of this section:"],[1,"(1) The false representation or implication that the debt collector is vouched for, bonded by, or affiliated with the United States or any State, including the use of any badge, uniform, or facsimile thereof."],[1,"(2) The false representation of—"],[2,"(A) the character, amount, or legal status of any debt; or"],[2,"(B) any services rendered or compensation which may be lawfully received by any debt collector for the collection of a debt."],[1,"(3) The false representation or implication that any individual is an attorney or that any communication is from an attorney."],[1,"(4) The representation or implication that nonpayment of any debt will result in the arrest or imprisonment of any person or the seizure, garnishment, attachment, or sale of any property or wages of any person unless such action is lawful and the debt collector or creditor intends to take such action."],[1,"(5) The threat to take any action that cannot legally be taken or that is not intended to be taken."],[1,"(6) The false representation or implication that a sale, referral, or other transfer of any interest in a debt shall cause the consumer to—"],[2,"(A) lose any claim or defense to payment of the debt; or"],[2,"(B) become subject to any practice prohibited by this subchapter."],[1,"(7) The false representation or implication that the consumer committed any crime or other conduct in order to disgrace the consumer."],[1,"(8) Communicating or threatening to communicate to any person credit information which is known or which should be known to be false, including the failure to communicate that a disputed debt is disputed."],[1,"(9) The use or distribution of any written communication which simulates or is falsely represented to be a document authorized, issued, or approved by any court, official, or agency of the United States or any State, or which creates a false impression as to its source, authorization, or approval."],[1,"(10) The use of any false representation or deceptive means to collect or attempt to collect any debt or to obtain information concerning a consumer."],[1,"(11) The failure to disclose in the initial written communication with the consumer and, in addition, if the initial communication with the consumer is oral, in that initial oral communication, that the debt collector is attempting to collect a debt and that any information obtained will be used for that purpose, and the failure to disclose in subsequent communications that the communication is from a debt collector, except that this paragraph shall not apply to a formal pleading made in connection with a legal action."],[1,"(12) The false representation or implication that accounts have been turned over to innocent purchasers for value."],[1,"(13) The false representation or implication that documents are legal process."],[1,"(14) The use of any business, company, or organization name other than the true name of the debt collector's business, company, or organization."],[1,"(15) The false representation or implication that documents are not legal process forms or do not require action by the consumer."],[1,"(16) The false representation or implication that a debt collector operates or is employed by a consumer reporting agency as defined by section 1681a(f) of this title."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/15/1692e?type=usc&year=mostrecent&link-type=html"},"head":"§1692e. False or misleading representations","tname":"Commerce and Trade","by":{"0":"3, 34","2":"2, 2, 2, 2, 2","3":"16"}},{"t":"usc","label":"15 U.S.C. § 1692f","url":"https://www.law.cornell.edu/uscode/text/15/1692f","subs":["(6)(A)","(6)(C)","(7)","(8)"],"stext":{"head":"§1692f. Unfair practices","paras":[[0,"A debt collector may not use unfair or unconscionable means to collect or attempt to collect any debt. Without limiting the general application of the foregoing, the following conduct is a violation of this section:"],[1,"(1) The collection of any amount (including any interest, fee, charge, or expense incidental to the principal obligation) unless such amount is expressly authorized by the agreement creating the debt or permitted by law."],[1,"(2) The acceptance by a debt collector from any person of a check or other payment instrument postdated by more than five days unless such person is notified in writing of the debt collector's intent to deposit such check or instrument not more than ten nor less than three business days prior to such deposit."],[1,"(3) The solicitation by a debt collector of any postdated check or other postdated payment instrument for the purpose of threatening or instituting criminal prosecution."],[1,"(4) Depositing or threatening to deposit any postdated check or other postdated payment instrument prior to the date on such check or instrument."],[1,"(5) Causing charges to be made to any person for communications by concealment of the true purpose of the communication. Such charges include, but are not limited to, collect telephone calls and telegram fees."],[1,"(6) Taking or threatening to take any nonjudicial action to effect dispossession or disablement of property if—"],[2,"(A) there is no present right to possession of the property claimed as collateral through an enforceable security interest;"],[2,"(B) there is no present intention to take possession of the property; or"],[2,"(C) the property is exempt by law from such dispossession or disablement."],[1,"(7) Communicating with a consumer regarding a debt by post card."],[1,"(8) Using any language or symbol, other than the debt collector's address, on any envelope when communicating with a consumer by use of the mails or by telegram, except that a debt collector may use his business name if such name does not indicate that he is in the debt collection business."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/15/1692f?type=usc&year=mostrecent&link-type=html"},"head":"§1692f. Unfair practices","tname":"Commerce and Trade","by":{"0":"3, 34, 35","2":"2, 20, 20, 19, 19","3":"16"}},{"t":"usc","label":"15 U.S.C. § 1692j","url":"https://www.law.cornell.edu/uscode/text/15/1692j","by":{"0":"35"}},{"t":"usc","label":"15 U.S.C. § 1692k","url":"https://www.law.cornell.edu/uscode/text/15/1692k","subs":["(a)","(a)(2)","(b)","(c)","(d)","(e)"],"stext":{"head":"§1692k. Civil liability","paras":[[0,"(a) Amount of damages"],[0,"Except as otherwise provided by this section, any debt collector who fails to comply with any provision of this subchapter with respect to any person is liable to such person in an amount equal to the sum of—"],[1,"(1) any actual damage sustained by such person as a result of such failure;"],[1,"(2)(A) in the case of any action by an individual, such additional damages as the court may allow, but not exceeding $1,000; or"],[1,"(B) in the case of a class action, (i) such amount for each named plaintiff as could be recovered under subparagraph (A), and (ii) such amount as the court may allow for all other class members, without regard to a minimum individual recovery, not to exceed the lesser of $500,000 or 1 per centum of the net worth of the debt collector; and"],[1,"(3) in the case of any successful action to enforce the foregoing liability, the costs of the action, together with a reasonable attorney's fee as determined by the court. On a finding by the court that an action under this section was brought in bad faith and for the purpose of harassment, the court may award to the defendant attorney's fees reasonable in relation to the work expended and costs."],[0,"(b) Factors considered by court"],[0,"In determining the amount of liability in any action under subsection (a), the court shall consider, among other relevant factors—"],[1,"(1) in any individual action under subsection (a)(2)(A), the frequency and persistence of noncompliance by the debt collector, the nature of such noncompliance, and the extent to which such noncompliance was intentional; or"],[1,"(2) in any class action under subsection (a)(2)(B), the frequency and persistence of noncompliance by the debt collector, the nature of such noncompliance, the resources of the debt collector, the number of persons adversely affected, and the extent to which the debt collector's noncompliance was intentional."],[0,"(c) Intent"],[0,"A debt collector may not be held liable in any action brought under this subchapter if the debt collector shows by a preponderance of evidence that the violation was not intentional and resulted from a bona fide error notwithstanding the maintenance of procedures reasonably adapted to avoid any such error."],[0,"(d) Jurisdiction"],[0,"An action to enforce any liability created by this subchapter may be brought in any appropriate United States district court without regard to the amount in controversy, or in any other court of competent jurisdiction, within one year from the date on which the violation occurs."],[0,"(e) Advisory opinions of Bureau"],[0,"No provision of this section imposing any liability shall apply to any act done or omitted in good faith in conformity with any advisory opinion of the Bureau, notwithstanding that after such act or omission has occurred, such opinion is amended, rescinded, or determined by judicial or other authority to be invalid for any reason."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/15/1692k?type=usc&year=mostrecent&link-type=html"},"op":5,"head":"§1692k. Civil liability","tname":"Commerce and Trade","by":{"0":"2, 4, 30","1":"passim","2":"1, 1, 1, 1, 1, 1"}},{"t":"usc","label":"21 U.S.C. § 335b","url":"https://www.law.cornell.edu/uscode/text/21/335b","by":{"0":"17"}},{"t":"usc","label":"28 U.S.C. § 1254","url":"https://www.law.cornell.edu/uscode/text/28/1254","subs":["(1)"],"by":{"0":"1"}},{"t":"usc","label":"28 U.S.C. § 1658","url":"https://www.law.cornell.edu/uscode/text/28/1658","subs":["(b)(1)"],"stext":{"head":"§1658. Time limitations on the commencement of civil actions arising under Acts of Congress","paras":[[0,"(a) Except as otherwise provided by law, a civil action arising under an Act of Congress enacted after the date of the enactment of this section may not be commenced later than 4 years after the cause of action accrues."],[0,"(b) Notwithstanding subsection (a), a private right of action that involves a claim of fraud, deceit, manipulation, or contrivance in contravention of a regulatory requirement concerning the securities laws, as defined in section 3(a)(47) of the Securities Exchange Act of 1934 (15 U.S.C. 78c(a)(47)), may be brought not later than the earlier of—"],[1,"(1) 2 years after the discovery of the facts constituting the violation; or"],[1,"(2) 5 years after such violation."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/28/1658?type=usc&year=mostrecent&link-type=html"},"head":"§1658. Time limitations on the commencement of civil actions arising under Acts of Congress","tname":"Judiciary and Judicial Procedure","by":{"0":"17","2":"11, 13"}},{"t":"law","label":"Pub. L. No. 104-208","url":"https://www.govinfo.gov/link/plaw/104/public/208","by":{"0":"34"}},{"t":"law","label":"Pub. L. No. 95-109","url":"https://www.govinfo.gov/link/statute/91/874","by":{"0":"passim"}},{"t":"case","label":"Ashcroft v. Iqbal","cite":"556 U.S. 662","y":2009,"id":"2008/07-1015","sc":1,"sum":"The Court found that high-ranking government officials were not liable for unconstitutional acts by subordinate officials.","sumSrc":"Oyez","by":{"1":"43"}},{"t":"case","label":"Bell Atl. Corp. v. Twombly","cite":"550 U.S. 544","y":2007,"id":"2006/05-1126","sc":1,"sum":"The Court ruled 7-2 that a plaintiff claiming a Section 1 violation must also allege facts that, if true, would suggest a conspiratorial agreement.","sumSrc":"Oyez","by":{"1":"43"}},{"t":"case","label":"Cada v. Baxter Healthcare Corp.","cite":"920 F.2d 446","y":1990,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.2d/920/446/","ar":3,"by":{"1":"39","2":"10"}},{"t":"case","label":"Conn. Nat. Bank v. Germain","cite":"503 U.S. 249","y":1992,"id":"1991/90-1791","sc":1,"op":2,"sum":"An interlocutory order issued by a district court sitting as a court of appeals in bankruptcy is appealable under the unambiguous language of 28 U. S. C. § 1292. That section provides for review in the courts of appeals, in certain circumstances, of \"[i]nterlocutory orders of the district courts,\" and does not limit such review to orders issued by district courts sitting as bankruptcy trial courts rather than …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"16, 19"}},{"t":"case","label":"Cozzarelli v. Inspire Pharm. Inc.","cite":"549 F.3d 618","y":2008,"court":"4th Cir.","url":"https://www.courtlistener.com/c/F.3d/549/618/","sum":"Explaining that “one of the primary purposes of Rule 9(b)” is “protecting defendants from the reputational harm that results from frivolous allegations of fraudulent conduct”.","sumSrc":"brief:1","by":{"1":"43, 44"}},{"t":"case","label":"Fed. Home Loan Mortg. Corp. v. Lamar","cite":"503 F.3d 504","y":2007,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.3d/503/504/","by":{"1":"25"}},{"t":"case","label":"Forbes v. Eagleson","cite":"228 F.3d 471","y":2000,"court":"3d Cir.","url":"https://www.courtlistener.com/c/F.3d/228/471/","by":{"1":"9"}},{"t":"case","label":"Foudy v. Indian River Cty. Sheriff’s Office","cite":"845 F.3d 1117","y":2017,"court":"11th Cir.","url":"https://www.courtlistener.com/c/F.3d/845/1117/","by":{"1":"31"}},{"t":"case","label":"Graham Cty. Soil & Water Conservation Dist. v. United States ex rel. Wilson","cite":"545 U.S. 409","y":2005,"id":"2004/04-169","sc":1,"op":1,"sum":"The Court ruled that the six-year statute of limitations did not apply to suits for retaliation. The majority opinion by Justice Clarence Thomas found the statute of limitations \"ambiguous.\" The ambiguity arose from the fact that the six-year limitation in the FCA starts from the time the false claim was made. Yet in a retaliation suit, no actual false claim needs to be alleged.","sumSrc":"Oyez","by":{"1":"14, 30, 39"}},{"t":"case","label":"Heimeshoff v. Hartford Life & Acc. Ins. Co.","cite":"571 U.S. 99","y":2013,"id":"2013/12-729","sc":1,"sum":"The Court held that the Employment Retirement Income Security Act does not mandate a statute of limitations, allowing both parties in an insurance suit to mutually agree on a timeframe in which civil suits may be brought to court.","sumSrc":"Oyez","by":{"1":"30"}},{"t":"case","label":"Klehr v. A.O. Smith Corp.","cite":"521 U.S. 179","y":1997,"id":"1996/96-663","sc":1,"op":1,"sum":"No and No. Justice Stephen Breyer wrote the opinion for a unanimous Court. The \"last predicate rule...lengthens the limitations period dramatically\" and thereby contradicts Congress's intention of ensuring a time limit for civil RICO claims.","sumSrc":"Oyez","by":{"1":"9, 39","2":"26","3":"17"}},{"t":"case","label":"Ladd v. United States","cite":"630 F.3d 1015","y":2010,"court":"Fed. Cir.","url":"https://www.courtlistener.com/c/F.3d/630/1015/","by":{"1":"31"}},{"t":"case","label":"Mangum v. Action Collection Serv., Inc.","cite":"575 F.3d 935","y":2009,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/575/935/","op":1,"by":{"1":"27","2":"21"}},{"t":"case","label":"Marshall-Mosby v. Corp. Receivables","cite":"205 F.3d 323","y":2000,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/205/323/","by":{"1":"27"}},{"t":"case","label":"Mattson v. U.S. West Comm’ns","cite":"967 F.2d 259","y":1992,"court":"8th Cir.","url":"https://www.courtlistener.com/c/F.2d/967/259/","by":{"1":"27"}},{"t":"case","label":"McQuiggin v. Perkins","cite":"569 U.S. 383","y":2013,"id":"2012/12-126","sc":1,"sum":"The Court held that proving actual innocence allows a petitioner to pursue habeas corpus relief regardless of a statute of limitations.","sumSrc":"Oyez","by":{"1":"38"}},{"t":"case","label":"Menominee Indian Tribe of Wis. v. United States","cite":"136 S. Ct. 750","y":2016,"id":"2015/14-510","sc":1,"op":1,"sum":"The Court determined that there were no extraordinary circumstances out of the Menominee Indian Tribe’s control to toll the statute of limitations from running.","sumSrc":"Oyez","by":{"1":"8, 9, 42","2":"26","3":"3"}},{"t":"case","label":"Murphy v. Equifax Check Servs., Inc.","cite":"35 F. Supp. 2d 200","y":1999,"court":"D. Conn.","url":"https://www.courtlistener.com/c/F.%20Supp.%202d/35/200/","by":{"1":"25"}},{"t":"case","label":"Order of Railroad Telegraphers v. Railway Express Agency, Inc.","cite":"321 U.S. 342","y":1944,"id":"scdb/1943-094","sc":1,"sum":"1. Failure of the carrier to give notice, to the representative of the employees, of an intended change affecting rates of pay of certain individual employees was in violation of § 6 of the Railway Labor Act of 1926, applicable to the collective agreement in question, and rendered ineffective the individual agreements entered into; and the award of the Adjustment Board, based on the collective agreement, was in …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"24"}},{"t":"case","label":"Ross v. Blake","cite":"136 S. Ct. 1850","y":2016,"id":"2015/15-339","sc":1,"sum":"The Court determined that the Prison Litigation Reform Act’s requirement to exhaust administrative remedies does not have a “special circumstances” exception.","sumSrc":"Oyez","by":{"1":"16","2":"11"}},{"t":"case","label":"Rubin v. United States","cite":"449 U.S. 424","y":1981,"id":"1980/79-1013","sc":1,"sum":"The pledge of stock to a bank as collateral for a loan is an \"offer or sale\" of a security under § 17 (a).","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"19"}},{"t":"case","label":"Shropshear v. Corp. Counsel of City of Chicago","cite":"275 F.3d 593","y":2001,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/275/593/","by":{"1":"39"}},{"t":"case","label":"Wallace v. Kato","cite":"549 U.S. 384","y":2007,"id":"2006/05-1240","sc":1,"sum":"The opinion by Justice Antonin Scalia held that \"the statute of limitations begins to run when the alleged false imprisonment ends.\" Since false imprisonment is detention without legal process, the Court ruled, the false imprisonment ends when legal processes begin. At that point, the clock begins to run on the time limit for filing a false imprisonment claim.","sumSrc":"Oyez","by":{"1":"30"}},{"t":"case","label":"Wike v. Vertrue, Inc.","cite":"566 F.3d 590","y":2009,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.3d/566/590/","by":{"1":"31"}},{"t":"case","label":"Wilson v. Garcia","cite":"471 U.S. 261","y":1985,"id":"1984/83-2146","sc":1,"sum":"The Court held that, in situations where a federal action does not have a statute of limitations, the practice has been to adopt a local limitation as long as that limitation is not inconsistent with a federal law or policy.","sumSrc":"Oyez","by":{"1":"23, 26"}},{"t":"case","label":"Wood v. Carpenter","cite":"101 U.S. 135","y":1879,"id":"scdb/1879-050","sc":1,"by":{"1":"23"}},{"t":"case","label":"Young v. United States","cite":"535 U.S. 43","y":2002,"id":"2001/00-1567","sc":1,"op":1,"sum":"The Court held section 507(a)(8)(A)(i)'s lookback period is tolled during the pendency of a prior bankruptcy petition. The Court reasoned that the three-year lookback period is a limitations period subject to traditional principles of equitable tolling and that nothing in the Bankruptcy Code precluded the equitable tolling of the lookback period.","sumSrc":"Oyez","by":{"1":"26","2":"14, 16, 21, 24, 25, 31"}},{"t":"usc","label":"12 U.S.C. § 3416","url":"https://www.law.cornell.edu/uscode/text/12/3416","stext":{"head":"§3416. Jurisdiction","paras":[[0,"An action to enforce any provision of this chapter may be brought in any appropriate United States district court without regard to the amount in controversy within three years from the date on which the violation occurs or the date of discovery of such violation, whichever is later."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/12/3416?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§3416. Jurisdiction","tname":"Banks and Banking","by":{"1":"12, 18"}},{"t":"usc","label":"15 U.S.C. § 78u-6","url":"https://www.law.cornell.edu/uscode/text/15/78u-6","by":{"1":"18"}},{"t":"usc","label":"15 U.S.C. § 80b-6","url":"https://www.law.cornell.edu/uscode/text/15/80b-6","by":{"1":"22"}},{"t":"usc","label":"15 U.S.C. § 1679i","url":"https://www.law.cornell.edu/uscode/text/15/1679i","stext":{"head":"§1679i. Statute of limitations","paras":[[0,"Any action to enforce any liability under this subchapter may be brought before the later of—"],[1,"(1) the end of the 5-year period beginning on the date of the occurrence of the violation involved; or"],[1,"(2) in any case in which any credit repair organization has materially and willfully misrepresented any information which—"],[2,"(A) the credit repair organization is required, by any provision of this subchapter, to disclose to any consumer; and"],[2,"(B) is material to the establishment of the credit repair organization's liability to the consumer under this subchapter,"],[1,"the end of the 5-year period beginning on the date of the discovery by the consumer of the misrepresentation."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/15/1679i?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§1679i. Statute of limitations","tname":"Commerce and Trade","by":{"1":"18"}},{"t":"usc","label":"15 U.S.C. § 1681p","url":"https://www.law.cornell.edu/uscode/text/15/1681p","subs":["(2000)","(1976)"],"by":{"1":"8, 12, 20","2":"13, 17"}},{"t":"usc","label":"15 U.S.C. § 1692g","url":"https://www.law.cornell.edu/uscode/text/15/1692g","subs":["(a)","(b)"],"by":{"1":"4, 34","2":"2, 20, 2"}},{"t":"usc","label":"15 U.S.C. § 1692l","url":"https://www.law.cornell.edu/uscode/text/15/1692l","subs":["(a)","(b)"],"stext":{"head":"§1692l. Administrative enforcement","paras":[[0,"(a) Federal Trade Commission"],[0,"The Federal Trade Commission shall be authorized to enforce compliance with this subchapter, except to the extent that enforcement of the requirements imposed under this subchapter is specifically committed to another Government agency under any of paragraphs (1) through (5) of subsection (b), subject to subtitle B of the Consumer Financial Protection Act of 2010 [12 U.S.C. 5511 et seq.]. For purpose of the exercise by the Federal Trade Commission of its functions and powers under the Federal Trade Commission Act (15 U.S.C. 41 et seq.), a violation of this subchapter shall be deemed an unfair or deceptive act or practice in violation of that Act. All of the functions and powers of the Federal Trade Commission under the Federal Trade Commission Act are available to the Federal Trade Commission to enforce compliance by any person with this subchapter, irrespective of whether that person is engaged in commerce or meets any other jurisdictional tests under the Federal Trade Commission Act, including the power to enforce the provisions of this subchapter, in the same manner as if the violation had been a violation of a Federal Trade Commission trade regulation rule."],[0,"(b) Applicable provisions of law"],[0,"Subject to subtitle B of the Consumer Financial Protection Act of 2010, compliance with any requirements imposed under this subchapter shall be enforced under—"],[1,"(1) section 8 of the Federal Deposit Insurance Act [12 U.S.C. 1818], by the appropriate Federal banking agency, as defined in section 3(q) of the Federal Deposit Insurance Act (12 U.S.C. 1813(q)), with respect to—"],[2,"(A) national banks, Federal savings associations, and Federal branches and Federal agencies of foreign banks;"],[2,"(B) member banks of the Federal Reserve System (other than national banks), branches and agencies of foreign banks (other than Federal branches, Federal agencies, and insured State branches of foreign banks), commercial lending companies owned or controlled by foreign banks, and organizations operating under section 25 or 25A of the Federal Reserve Act [12 U.S.C. 601 et seq., 611 et seq.]; and"],[2,"(C) banks and State savings associations insured by the Federal Deposit Insurance Corporation (other than members of the Federal Reserve System), and insured State branches of foreign banks;"],[1,"(2) the Federal Credit Union Act [12 U.S.C. 1751 et seq.], by the Administrator of the National Credit Union Administration with respect to any Federal credit union;"],[1,"(3) subtitle IV of title 49, by the Secretary of Transportation, with respect to all carriers subject to the jurisdiction of the Surface Transportation Board;"],[1,"(4) part A of subtitle VII of title 49, by the Secretary of Transportation with respect to any air carrier or any foreign air carrier subject to that part;"],[1,"(5) the Packers and Stockyards Act, 1921 [7 U.S.C. 181 et seq.] (except as provided in section 406 of that Act [7 U.S.C. 226, 227]), by the Secretary of Agriculture with respect to any activities subject to that Act; and"],[1,"(6) subtitle E of the Consumer Financial Protection Act of 2010 [12 U.S.C. 5561 et seq.], by the Bureau, with respect to any person subject to this subchapter."],[0,"The terms used in paragraph (1) that are not defined in this subchapter or otherwise defined in section 3(s) of the Federal Deposit Insurance Act (12 U.S.C. 1813(s)) shall have the meaning given to them in section 1(b) of the International Banking Act of 1978 (12 U.S.C. 3101)."],[0,"(c) Agency powers"],[0,"For the purpose of the exercise by any agency referred to in subsection (b) of its powers under any Act referred to in that subsection, a violation of any requirement imposed under this subchapter shall be deemed to be a violation of a requirement imposed under that Act. In addition to its powers under any provision of law specifically referred to in subsection (b), each of the agencies referred to in that subsection may exercise, for the purpose of enforcing compliance with any requirement imposed under this subchapter any other authority conferred on it by law, except as provided in subsection (d)."],[0,"(d) Rules and regulations"],[0,"Except as provided in section 1029(a) of the Consumer Financial Protection Act of 2010 [12 U.S.C. 5519(a)], the Bureau may prescribe rules with respect to the collection of debts by debt collectors, as defined in this subchapter."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/15/1692l?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§1692l. Administrative enforcement","tname":"Commerce and Trade","by":{"1":"4","2":"1, 2, 1"}},{"t":"usc","label":"28 U.S.C. § 2462","url":"https://www.law.cornell.edu/uscode/text/28/2462","by":{"1":"8, 13, 22"}},{"t":"usc","label":"50 U.S.C. § 4611","url":"https://www.law.cornell.edu/uscode/text/50/4611","by":{"1":"18"}},{"t":"rule","label":"Fed. R. Civ. P. 9","url":"https://www.law.cornell.edu/rules/frcp/rule_9","by":{"1":"43, 44"}},{"t":"case","label":"Allen ex. rel. Martin v. LaSalle Bank, N.A.","cite":"629 F.3d 364","y":2011,"court":"3d Cir.","url":"https://www.courtlistener.com/c/F.3d/629/364/","by":{"2":"3"}},{"t":"case","label":"Amy v. Watertown (No. 2)","cite":"130 U.S. 320","y":1889,"id":"scdb/1888-175","sc":1,"sum":"The general rule respecting' statutes of limitation is that the language of the act must prevail, and that no reason based on apparent inconvenience or hardship will justify a departure from it.","sumSrc":"Headnote (U.S. Reports)","by":{"2":"29"}},{"t":"case","label":"Avery v. Cleary","cite":"132 U.S. 604","y":1890,"id":"scdb/1889-079","sc":1,"sum":"On the facts, as stated in the opinion of the court, it is held, that this suit is one between an assignee in bankruptcy and one claiming an adverse interest touching the property which is the subject of controversy, within the meaning of Rev. Stat. § 5057, prescribing a limitation for the commencement of such an action.","sumSrc":"Headnote (U.S. Reports)","by":{"2":"29, 30, 31"}},{"t":"case","label":"Credit Suisse Sec. (USA) LLC v. Simmonds","cite":"566 U.S. 221","y":2012,"id":"2011/10-1261","sc":1,"op":1,"sum":"The Court held that Section 16(b) of the 1934 Securities Exchange Act is subject to tolling, where tolling starts after the filing of a Section 16(a) claim.","sumSrc":"Oyez","by":{"2":"26, 27","3":"12"}},{"t":"case","label":"Department of Homeland Sec. v. MacLean","cite":"135 S. Ct. 913","y":2015,"id":"2014/13-894","sc":1,"sum":"The Court ruled that the Whistleblower Protection Act bars an agency from taking enforcement action against employees who intentionally disclose sensitive security information.","sumSrc":"Oyez","by":{"2":"13"}},{"t":"case","label":"Food Mktg. Inst. v. Argus Leader Media","cite":"139 S. Ct. 2356","y":2019,"id":"2018/18-481","sc":1,"sum":"Where commercial or financial information is both customarily and actually treated as private by its owner and provided to the government under an assurance of privacy, the information is “confidential” within the meaning of 5 U. S. C. §552(b)(4), the Freedom of Information Act’s Exemption 4.","sumSrc":"Holding (supremecourt.gov)","by":{"2":"12, 16"}},{"t":"case","label":"Harris Trust & Sav. Bank v. Salomon Smith Barney Inc.","cite":"530 U.S. 238","y":2000,"id":"1999/99-579","sc":1,"sum":"The Court held that Section 502(a)(3)'s authorization to a plan \"participant, beneficiary, or fiduciary\" to bring a civil action for \"appropriate equitable relief\" extends to a suit against a nonfiduciary \"party in interest\" to a prohibited transaction barred by section 406(a). \"We reject,\" wrote Justice Thomas that, \"absent a substantive provision of ERISA expressly imposing a duty upon a nonfiduciary party in interest, the nonfiduciary party may not be held liable under [section 502(a)(3)].\" Justice Thomas concluded that \"[section 502(a)(3)] itself imposes certain duties, and therefore that liability under that provision does not depend on whether ERISA's substantive provisions impose a specific duty on the party being sued.\".","sumSrc":"Oyez","by":{"2":"11"}},{"t":"case","label":"Kirkendall v. Department of the Army","cite":"479 F.3d 830","y":2007,"url":"https://www.courtlistener.com/c/F.3d/479/830/","by":{"2":"25"}},{"t":"case","label":"Mathews v. Kidder, Peabody & Co.","cite":"260 F.3d 239","y":2001,"court":"3d Cir.","url":"https://www.courtlistener.com/c/F.3d/260/239/","by":{"2":"6"}},{"t":"case","label":"Mertens v. Hewitt Assocs.","cite":"508 U.S. 248","y":1993,"id":"1992/91-1671","sc":1,"sum":"ERISA does not authorize suits for money damages against nonfiduciaries who knowingly participate in a fiduciary's breach of fiduciary duty. ERISA §502(a)(3) permits plan participants to bring civil actions to obtain \"appropriate equitable relief\" to redress violations of the statute or a plan. Assuming, arguendo,that this creates a cause of action against nonfiduciaries who knowingly assist in a fiduciary's breach …","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"19"}},{"t":"case","label":"National R.R. Passenger Corp. v. Morgan","cite":"536 U.S. 101","y":2002,"id":"2001/00-1614","sc":1,"sum":"The Court held that Title VII of the Civil Rights Act of 1964 precludes recovery for discrete acts of discrimination or retaliation that occur outside the statutory time period.","sumSrc":"Oyez","by":{"2":"12"}},{"t":"case","label":"Nutraceutical Corp. v. Lambert","cite":"139 S. Ct. 710","y":2019,"id":"2018/17-1094","sc":1,"sum":"Federal Rule of Civil Procedure 23(f), which establishes a 14-day deadline to seek permission to appeal an order granting or denying class certification, is not subject to equitable tolling.","sumSrc":"Holding (supremecourt.gov)","by":{"2":"24"}},{"t":"case","label":"OBB Personenverkehr AG v. Sachs","cite":"136 S. Ct. 390","y":2015,"id":"2015/13-1067","sc":1,"sum":"The Court held that the commercial activity exception to the Foreign Sovereign Immunity Act only applies when the suit is based upon activity that took place in the United States, and it was not sufficient to establish a single element of the claim in question.","sumSrc":"Oyez","by":{"2":"27"}},{"t":"case","label":"Obduskey v. McCarthy & Holthus LLP","cite":"139 S. Ct. 1029","y":2019,"id":"2018/17-1307","sc":1,"sum":"A business engaged in no more than nonjudicial foreclosure proceedings is not a “debt collector” under the Fair Debt Collection Practices Act, except for the limited purpose of enforcing security interests under 15 U. S. C. §1692f(6).","sumSrc":"Holding (supremecourt.gov)","by":{"2":"22"}},{"t":"case","label":"Ramírez-Carlo v. United States","cite":"496 F.3d 41","y":2007,"court":"1st Cir.","url":"https://www.courtlistener.com/c/F.3d/496/41/","sum":"Noting that this Court has “treated equitable estoppel as a form of equitable tolling” (citing Irwin, 498 U.S. at 96).","sumSrc":"brief:2","by":{"2":"25"}},{"t":"case","label":"Rodriguez v. United States","cite":"480 U.S. 522","y":1987,"id":"1986/86-5504","sc":1,"sum":"Section 3147 does not divest sentencing judges of their § 3651 authority. Nothing in the language of the two provisions suggests the existence of an \"irreconcilable conflict\" from which an intent to work an implicit partial repeal of § 3651 may be inferred; to the contrary, the provisions fit together quite sensibly. Moreover, the totality of the legislative history of the Act of which §3147 is a part demonstrates …","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"22"}},{"t":"case","label":"Rosenthal v. Walker","cite":"111 U.S. 185","y":1884,"id":"scdb/1883-208","sc":1,"sum":"Bankruptcy — Statute of IAmitations — Evidence.","sumSrc":"Headnote (U.S. Reports)","by":{"2":"29, 30"}},{"t":"case","label":"SEC v. Capital Gains Research Bureau, Inc.","cite":"375 U.S. 180","y":1963,"id":"1963/42","sc":1,"by":{"2":"31"}},{"t":"case","label":"Sherwood v. Sutton","cite":"21 F. Cas. 1303","y":1828,"court":"C.C.D.N.H.","url":"https://www.courtlistener.com/c/F.%20Cas./21/1303/","op":2,"by":{"2":"28"}},{"t":"case","label":"Traer v. Clews","cite":"115 U.S. 528","y":1885,"id":"scdb/1885-037","sc":1,"sum":"A suit in which the purchaser from a trustee in bankruptcy of property of the bankrupt estate asserts title against a defendant claiming an adverse interest therein, though brought more than, two years after the cause of action accrues to the trustee, is not barréd by the limitation of two years prescribed by Rev. Stat. § 5057, if the defendant acquired title by a fraud practised by him on the trustee, and the fraud …","sumSrc":"Headnote (U.S. Reports)","by":{"2":"29, 30"}},{"t":"case","label":"United States v. American Trucking Ass’ns","cite":"310 U.S. 534","y":1940,"id":"scdb/1939-042","sc":1,"sum":"1. The power of the Interstate Commerce Commission under the Motor Carrier Act, 1935, § 204 (a), to establish reasonable requirements with respect tolthe qualifications and maximum hou'rs of service of employees of motor carriers, is confined to those employees whose duties affect safety of operation. Pp. 546, 553.","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"18"}},{"t":"case","label":"Wahl v. Midland Credit Mgmt., Inc.","cite":"556 F.3d 643","y":2009,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/556/643/","by":{"2":"3"}},{"t":"case","label":"William A. Graham Co. v. Haughey","cite":"646 F.3d 138","y":2011,"url":"https://www.courtlistener.com/c/F.3d/646/138/","by":{"2":"10, 23"}},{"t":"usc","label":"15 U.S.C. § 1681","url":"https://www.law.cornell.edu/uscode/text/15/1681","by":{"2":"17"}},{"t":"usc","label":"15 U.S.C. § 1692c-1692i","url":"https://www.law.cornell.edu/uscode/text/15/1692c-1692i","by":{"2":"2"}},{"t":"usc","label":"45 U.S.C. § 51","url":"https://www.law.cornell.edu/uscode/text/45/51","by":{"2":"16"}},{"t":"usc","label":"45 U.S.C. § 56","url":"https://www.law.cornell.edu/uscode/text/45/56","by":{"2":"16"}},{"t":"usc","label":"5 U.S.C. § 552a","url":"https://www.law.cornell.edu/uscode/text/5/552a","subs":["(g)(5)(1976)"],"by":{"2":"13, 14"}},{"t":"usc","label":"7 U.S.C. § 210","url":"https://www.law.cornell.edu/uscode/text/7/210","subs":["(a)(1976)"],"by":{"2":"14"}},{"t":"usc","label":"7 U.S.C. § 499f","url":"https://www.law.cornell.edu/uscode/text/7/499f","subs":["(a)(1976)"],"by":{"2":"14"}},{"t":"usc","label":"10 U.S.C. § 2733","url":"https://www.law.cornell.edu/uscode/text/10/2733","subs":["(b)(1)(1976)"],"by":{"2":"14"}},{"t":"usc","label":"15 U.S.C. § 77m","url":"https://www.law.cornell.edu/uscode/text/15/77m","subs":["(1976)"],"stext":{"head":"§77m. Limitation of actions","paras":[[0,"No action shall be maintained to enforce any liability created under section 77k or 77l(a)(2) of this title unless brought within one year after the discovery of the untrue statement or the omission, or after such discovery should have been made by the exercise of reasonable diligence, or, if the action is to enforce a liability created under section 77l(a)(1) of this title, unless brought within one year after the violation upon which it is based. In no event shall any such action be brought to enforce a liability created under section 77k or 77l(a)(1) of this title more than three years after the security was bona fide offered to the public, or under section 77l(a)(2) of this title more than three years after the sale."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/15/77m?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§77m. Limitation of actions","tname":"Commerce and Trade","by":{"2":"13"}},{"t":"usc","label":"15 U.S.C. § 77www","url":"https://www.law.cornell.edu/uscode/text/15/77www","subs":["(a)(1976)"],"by":{"2":"13"}},{"t":"usc","label":"15 U.S.C. § 78i","url":"https://www.law.cornell.edu/uscode/text/15/78i","subs":["(e)(1976)"],"by":{"2":"13"}},{"t":"usc","label":"15 U.S.C. § 78r","url":"https://www.law.cornell.edu/uscode/text/15/78r","subs":["(c)(1976)"],"by":{"2":"13"}},{"t":"usc","label":"15 U.S.C. § 1711","url":"https://www.law.cornell.edu/uscode/text/15/1711","subs":["(1976)"],"by":{"2":"13"}},{"t":"usc","label":"19 U.S.C. § 1621","url":"https://www.law.cornell.edu/uscode/text/19/1621","subs":["(1976)"],"stext":{"head":"§1621. Limitation of actions","paras":[[0,"No suit or action to recover any duty under section 1592(d), 1593a(d) of this title, or any pecuniary penalty or forfeiture of property accruing under the customs laws shall be instituted unless such suit or action is commenced within five years after the time when the alleged offense was discovered, or in the case of forfeiture, within 2 years after the time when the involvement of the property in the alleged offense was discovered, whichever was later; except that—"],[1,"(1) in the case of an alleged violation of section 1592 or 1593a of this title, no suit or action (including a suit or action for restoration of lawful duties under subsection (d) of such sections) may be instituted unless commenced within 5 years after the date of the alleged violation or, if such violation arises out of fraud, within 5 years after the date of discovery of fraud, and"],[1,"(2) the time of the absence from the United States of the person subject to the penalty or forfeiture, or of any concealment or absence of the property, shall not be reckoned within the 5-year period of limitation."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/19/1621?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§1621. Limitation of actions","tname":"Customs Duties","by":{"2":"13"}},{"t":"usc","label":"22 U.S.C. § 2356","url":"https://www.law.cornell.edu/uscode/text/22/2356","subs":["(a)(1976)"],"by":{"2":"14"}},{"t":"usc","label":"26 U.S.C. § 7217","url":"https://www.law.cornell.edu/uscode/text/26/7217","subs":["(c)(1976)"],"stext":{"head":"§7217. Prohibition on executive branch influence over taxpayer audits and other investigations","paras":[[0,"(a) Prohibition"],[0,"It shall be unlawful for any applicable person to request, directly or indirectly, any officer or employee of the Internal Revenue Service to conduct or terminate an audit or other investigation of any particular taxpayer with respect to the tax liability of such taxpayer."],[0,"(b) Reporting requirement"],[0,"Any officer or employee of the Internal Revenue Service receiving any request prohibited by subsection (a) shall report the receipt of such request to the Treasury Inspector General for Tax Administration."],[0,"(c) Exceptions"],[0,"Subsection (a) shall not apply to any written request made—"],[1,"(1) to an applicable person by or on behalf of the taxpayer and forwarded by such applicable person to the Internal Revenue Service;"],[1,"(2) by an applicable person for disclosure of return or return information under section 6103 if such request is made in accordance with the requirements of such section; or"],[1,"(3) by the Secretary of the Treasury as a consequence of the implementation of a change in tax policy."],[0,"(d) Penalty"],[0,"Any person who willfully violates subsection (a) or fails to report under subsection (b) shall be punished upon conviction by a fine in any amount not exceeding $5,000, or imprisonment of not more than 5 years, or both, together with the costs of prosecution."],[0,"(e) Applicable person"],[0,"For purposes of this section, the term \"applicable person\" means—"],[1,"(1) the President, the Vice President, any employee of the executive office of the President, and any employee of the executive office of the Vice President; and"],[1,"(2) any individual (other than the Attorney General of the United States) serving in a position specified in section 5312 of title 5, United States Code."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/26/7217?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§7217. Prohibition on executive branch influence over taxpayer audits and other investigations","tname":"Internal Revenue Code","by":{"2":"13, 14"}},{"t":"usc","label":"28 U.S.C. § 2401","url":"https://www.law.cornell.edu/uscode/text/28/2401","subs":["(1976)"],"by":{"2":"14"}},{"t":"usc","label":"29 U.S.C. § 1113","url":"https://www.law.cornell.edu/uscode/text/29/1113","subs":["(1976)"],"stext":{"head":"§1113. Limitation of actions","paras":[[0,"No action may be commenced under this subchapter with respect to a fiduciary's breach of any responsibility, duty, or obligation under this part, or with respect to a violation of this part, after the earlier of—"],[1,"(1) six years after (A) the date of the last action which constituted a part of the breach or violation, or (B) in the case of an omission the latest date on which the fiduciary could have cured the breach or violation, or"],[1,"(2) three years after the earliest date on which the plaintiff had actual knowledge of the breach or violation;"],[0,"except that in the case of fraud or concealment, such action may be commenced not later than six years after the date of discovery of such breach or violation."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/29/1113?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§1113. Limitation of actions","tname":"Labor","by":{"2":"13"}},{"t":"usc","label":"31 U.S.C. § 241","url":"https://www.law.cornell.edu/uscode/text/31/241","subs":["(c)(1)(1976)"],"by":{"2":"14"}},{"t":"usc","label":"32 U.S.C. § 715","url":"https://www.law.cornell.edu/uscode/text/32/715","subs":["(b)(1)(1976)"],"by":{"2":"14"}},{"t":"usc","label":"38 U.S.C. § 236","url":"https://www.law.cornell.edu/uscode/text/38/236","subs":["(1976)"],"by":{"2":"14"}},{"t":"usc","label":"45 U.S.C. § 153","url":"https://www.law.cornell.edu/uscode/text/45/153","subs":["(r)(1976)"],"by":{"2":"14"}},{"t":"usc","label":"47 U.S.C. § 415","url":"https://www.law.cornell.edu/uscode/text/47/415","subs":["(a)"],"by":{"2":"14"}},{"t":"usc","label":"49 U.S.C. § 16","url":"https://www.law.cornell.edu/uscode/text/49/16","subs":["(3)(a)"],"by":{"2":"14"}},{"t":"usc","label":"49 U.S.C. § 908","url":"https://www.law.cornell.edu/uscode/text/49/908","by":{"2":"14"}},{"t":"case","label":"Arbaugh v. Y&H Corp.","cite":"546 U.S. 500","y":2006,"id":"2005/04-944","sc":1,"sum":"The Court held that the number-of-employees requirement is an element of the merits of a Title VII claim, not a jurisdictional limitation.","sumSrc":"Oyez","by":{"3":"5"}},{"t":"case","label":"Boumediene v. Bush","cite":"553 U.S. 723","y":2008,"id":"2007/06-1195","sc":1,"sum":"The Court held that the Military Commissions Act of 2006 violated the Suspension Clause of the Constitution.","sumSrc":"Oyez","by":{"3":"7"}},{"t":"case","label":"Department of Transp. v. Association of Am. Railroads","cite":"135 S. Ct. 1225","y":2015,"url":"https://www.courtlistener.com/c/S.%20Ct./135/1225/","sc":1,"by":{"3":"18"}},{"t":"case","label":"International Soc'y for Krishna Consciousness, Inc. v. Lee","cite":"505 U.S. 672","y":1992,"id":"1991/91-155","sc":1,"op":3,"sum":"In a related case, the Court held invalid the airport authority's ban on literature distribution in airport terminals.","sumSrc":"Oyez","by":{"3":"6"}},{"t":"case","label":"Ledbetter v. Goodyear Tire & Rubber Co.","cite":"550 U.S. 618","y":2007,"id":"2006/05-1074","sc":1,"sum":"The Court ruled that a plaintiff cannot bring a salary discrimination suit under Title VII of the Civil Rights Act when the disparate pay is the result of decisions made outside of the 180-day limitations period.","sumSrc":"Oyez","by":{"3":"10"}},{"t":"case","label":"Manhattan Cmty. Access Corp. v. Halleck","cite":"139 S. Ct. 1921","y":2019,"id":"2018/17-1702","sc":1,"sum":"The Court held that Manhattan Community Access Corp, which operates public access channels, is not a state actor subject to constitutional liability.","sumSrc":"Oyez","by":{"3":"15"}},{"t":"case","label":"Pleasant Grove City v. Summum","cite":"555 U.S. 460","y":2009,"id":"2008/07-665","sc":1,"sum":"The Court held that a city's refusal to place an organization's monument in a public park is not a violation the organization's First Amendment rights.","sumSrc":"Oyez","by":{"3":"6"}},{"t":"case","label":"Republic of Sudan v. Harrison","cite":"139 S. Ct. 1048","y":2019,"id":"2018/16-1094","sc":1,"sum":"When civil process is served on a foreign state under the Foreign Sovereign Immunities Act of 1976, 28 U. S. C. §1608(a)(3) requires a mailing to be sent directly to the foreign minister’s office in the foreign state.","sumSrc":"Holding (supremecourt.gov)","by":{"3":"10"}},{"t":"usc","label":"42 U.S.C. § 2000e-5","url":"https://www.law.cornell.edu/uscode/text/42/2000e-5","subs":["(e)(1)"],"by":{"3":"10"}},{"t":"rule","label":"Fed. R. Civ. P. 15","url":"https://www.law.cornell.edu/rules/frcp/rule_15","subs":["(a)(2)"],"by":{"3":"18"}}]};